import { randomUUID, randomBytes, scryptSync, timingSafeEqual, createHash } from 'node:crypto';

export class ApiError extends Error {
  constructor(status, code, message) {
    super(message || code);
    this.status = status;
    this.code = code;
  }
}

export const bad = (m) => new ApiError(400, 'validation', m);
export const notFound = (m = 'not found') => new ApiError(404, 'not_found', m);
export const forbidden = (m = 'forbidden') => new ApiError(403, 'forbidden', m);
export const conflict = (m = 'conflict') => new ApiError(409, 'conflict', m);

export const newId = () => randomUUID();
export const randomToken = () => 'pmt_' + randomBytes(32).toString('base64url');
export const sha256 = (s) => createHash('sha256').update(s).digest('hex');

export function hashPassword(pw) {
  const salt = randomBytes(16).toString('hex');
  return `${salt}:${scryptSync(pw, salt, 64).toString('hex')}`;
}

export function verifyPassword(pw, stored) {
  const [salt, hex] = String(stored).split(':');
  if (!salt || !hex) return false;
  const actual = scryptSync(pw, salt, 64);
  const expected = Buffer.from(hex, 'hex');
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}

export const PRIORITIES = ['urgent', 'high', 'medium', 'low', 'none'];
export const ISSUE_TYPES = ['bug', 'feature', 'task', 'epic', 'subtask'];
export const WS_ROLES = ['admin', 'member', 'guest'];
export const PROJECT_ROLES = ['lead', 'developer', 'viewer'];
export const CATEGORIES = ['backlog', 'unstarted', 'started', 'completed'];
export const LINK_TYPES = ['blocks', 'relates', 'duplicates'];
export const EVENTS = ['issue.created', 'issue.updated', 'issue.deleted', 'comment.created'];

export function isValidDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(`${s}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}

export function reqStr(v, name, max) {
  if (typeof v !== 'string' || !v.trim()) throw bad(`${name} is required`);
  const t = v.trim();
  if (t.length > max) throw bad(`${name} is too long`);
  return t;
}

export function optStr(v, name, max) {
  if (v === undefined || v === null) return null;
  if (typeof v !== 'string') throw bad(`${name} must be a string`);
  if (v.length > max) throw bad(`${name} is too long`);
  return v;
}

export function reqPassword(v) {
  if (typeof v !== 'string' || v.length < 8) throw bad('password must be at least 8 characters');
  if (v.length > 200) throw bad('password is too long');
  return v;
}

export function pick(v, list, name) {
  if (!list.includes(v)) throw bad(`invalid ${name}`);
  return v;
}

// RFC 4180 CSV helpers.

// Returns [{ line, fields }] where line is the 1-based physical line a record starts on.
export function parseCsv(text) {
  let s = String(text ?? '');
  if (s.charCodeAt(0) === 0xfeff) s = s.slice(1);
  const records = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let line = 1;
  let recStart = 1;
  let fieldQuoted = false;

  const endRecord = () => {
    row.push(field);
    const isBlank = row.length === 1 && row[0] === '' && !fieldQuoted;
    if (!isBlank) records.push({ line: recStart, fields: row });
    row = [];
    field = '';
    fieldQuoted = false;
  };

  for (let i = 0; i < s.length; ) {
    const c = s[i];
    if (inQuotes) {
      if (c === '"') {
        if (s[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      if (c === '\n') line++;
      field += c; i++; continue;
    }
    if (c === '"' && field === '') { inQuotes = true; fieldQuoted = true; i++; continue; }
    if (c === ',') { row.push(field); field = ''; fieldQuoted = false; i++; continue; }
    if (c === '\r') { i++; continue; }
    if (c === '\n') {
      endRecord(); line++; recStart = line; i++; continue;
    }
    field += c; i++;
  }
  if (inQuotes) throw new Error('unterminated quoted field in CSV');
  if (field !== '' || row.length > 0 || fieldQuoted) endRecord();
  return records;
}

export function csvEscape(v) {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function csvLine(fields) {
  return fields.map(csvEscape).join(',') + '\r\n';
}

import { createHmac } from 'node:crypto';

const sleep = (ms) => new Promise((resolve) => {
  const t = setTimeout(resolve, ms);
  t.unref?.();
});

export function signBody(secret, body) {
  return 'sha256=' + createHmac('sha256', secret).update(body).digest('hex');
}

// Delivers a signed JSON payload with up to 3 attempts. Updates `delivery` in place.
// `status` is the last HTTP status code received (null if none); `lastError` describes failures.
export async function deliver({ url, secret, body, delivery, onChange }) {
  const signature = signBody(secret, body);
  for (let attempt = 1; attempt <= 3; attempt++) {
    delivery.attempts = attempt;
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'x-pm-signature': signature,
          'x-pm-event': delivery.event,
        },
        body,
        signal: AbortSignal.timeout(5000),
      });
      delivery.status = res.status;
      await res.arrayBuffer().catch(() => {});
      if (res.ok) {
        delivery.lastError = null;
        onChange?.();
        return;
      }
      delivery.lastError = `HTTP ${res.status}`;
    } catch (err) {
      delivery.lastError = err?.message || String(err);
    }
    onChange?.();
    if (attempt < 3) await sleep(100 * attempt);
  }
}

import { ISSUE_TYPES, PRIORITIES, bad, isValidDate } from './util.js';

const QUALIFIERS = new Set(['status', 'type', 'priority', 'assignee', 'label', 'sprint', 'is', 'due', 'points', 'key']);

function parseQualifier(field, value) {
  switch (field) {
    case 'status':
      return { field, value: value.toLowerCase() };
    case 'type': {
      const v = value.toLowerCase();
      if (!ISSUE_TYPES.includes(v)) throw bad(`invalid type "${value}"`);
      return { field, value: v };
    }
    case 'priority': {
      const v = value.toLowerCase();
      if (!PRIORITIES.includes(v)) throw bad(`invalid priority "${value}"`);
      return { field, value: v };
    }
    case 'assignee':
      return { field, value: value.toLowerCase() };
    case 'label':
      return { field, value: value.toLowerCase() };
    case 'sprint':
      return { field, value };
    case 'is': {
      const v = value.toLowerCase();
      if (v !== 'open' && v !== 'resolved') throw bad(`invalid is:"${value}"`);
      return { field, value: v };
    }
    case 'due': {
      const m = /^(<=|>=|<|>|=)?(.+)$/.exec(value);
      if (!isValidDate(m[2])) throw bad(`invalid due date "${value}"`);
      return { field, op: m[1] || '=', value: m[2] };
    }
    case 'points': {
      const m = /^(<=|>=|<|>|=)?(\d+(?:\.\d+)?)$/.exec(value);
      if (!m) throw bad(`invalid points "${value}"`);
      return { field, op: m[1] || '=', value: Number(m[2]) };
    }
    case 'key': {
      const v = value.toUpperCase();
      if (!/^[A-Z]{2,10}-\d+$/.test(v)) throw bad(`invalid key "${value}"`);
      return { field, value: v };
    }
    default:
      throw bad(`unknown qualifier "${field}"`);
  }
}

// Parses the search query language into a list of terms. Throws ApiError 400 when malformed.
export function parseQuery(q) {
  const terms = [];
  const s = String(q ?? '');
  let i = 0;
  while (i < s.length) {
    while (i < s.length && /\s/.test(s[i])) i++;
    if (i >= s.length) break;
    let neg = false;
    if (s[i] === '-' && i + 1 < s.length && !/\s/.test(s[i + 1])) { neg = true; i++; }
    let buf = '';
    let inQuote = false;
    const startsQuoted = s[i] === '"';
    while (i < s.length) {
      const c = s[i];
      if (c === '"') { inQuote = !inQuote; i++; continue; }
      if (!inQuote && /\s/.test(c)) break;
      buf += c;
      i++;
    }
    if (inQuote) throw bad('unterminated quote in query');
    const m = startsQuoted ? null : /^([A-Za-z]+):(.*)$/.exec(buf);
    if (m) {
      const field = m[1].toLowerCase();
      if (!QUALIFIERS.has(field)) throw bad(`unknown qualifier "${m[1]}"`);
      if (m[2] === '') throw bad(`empty value for "${field}"`);
      terms.push({ neg, ...parseQualifier(field, m[2]) });
    } else if (buf !== '') {
      terms.push({ neg, field: 'text', value: buf.toLowerCase() });
    }
  }
  return terms;
}

const cmp = (a, op, b) => {
  switch (op) {
    case '<': return a < b;
    case '<=': return a <= b;
    case '>': return a > b;
    case '>=': return a >= b;
    default: return a === b;
  }
};

// env: { userId, done(issue) -> bool, usernameOf(userId), activeSprintId(projectId) }
function testTerm(t, issue, env) {
  switch (t.field) {
    case 'text':
      return issue.title.toLowerCase().includes(t.value) ||
        (issue.description || '').toLowerCase().includes(t.value);
    case 'status':
      return issue.status.toLowerCase() === t.value;
    case 'type':
      return issue.type === t.value;
    case 'priority':
      return issue.priority === t.value;
    case 'assignee':
      if (t.value === 'none') return !issue.assigneeId;
      if (t.value === 'me') return issue.assigneeId === env.userId;
      return !!issue.assigneeId && String(env.usernameOf(issue.assigneeId) || '').toLowerCase() === t.value;
    case 'label':
      return issue.labels.some((l) => l.toLowerCase() === t.value);
    case 'sprint':
      if (t.value === 'none') return !issue.sprintId;
      if (t.value === 'active') return !!issue.sprintId && issue.sprintId === env.activeSprintId(issue.projectId);
      return issue.sprintId === t.value;
    case 'is':
      return t.value === 'resolved' ? env.done(issue) : !env.done(issue);
    case 'due':
      return !!issue.dueDate && cmp(issue.dueDate, t.op, t.value);
    case 'points':
      return issue.storyPoints !== null && issue.storyPoints !== undefined && cmp(issue.storyPoints, t.op, t.value);
    case 'key':
      return issue.key.toUpperCase() === t.value;
    default:
      return false;
  }
}

export function matchesAll(terms, issue, env) {
  return terms.every((t) => {
    const r = testTerm(t, issue, env);
    return t.neg ? !r : r;
  });
}

