* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; background: #f4f5f7; color: #172b4d; font-size: 14px; }
a { color: #0052cc; text-decoration: none; }
a:hover { text-decoration: underline; }
button { cursor: pointer; border: 1px solid #c1c7d0; background: #fff; border-radius: 3px; padding: 4px 10px; font: inherit; }
button.primary { background: #0052cc; color: #fff; border-color: #0052cc; }
button.danger { color: #de350b; }
button.link { border: none; background: none; color: #0052cc; padding: 0; }
input, select, textarea { font: inherit; padding: 4px 6px; border: 1px solid #c1c7d0; border-radius: 3px; background: #fff; }
textarea { width: 100%; min-height: 60px; }
label { display: block; margin: 6px 0; }
label input, label select, label textarea { display: block; width: 100%; margin-top: 2px; }
h1, h2, h3 { font-weight: 600; }
h2 { margin: 8px 0; }
.hidden { display: none !important; }
.error { color: #de350b; min-height: 1em; }
.muted { color: #6b778c; }
.top { display: flex; align-items: center; gap: 12px; background: #172b4d; color: #fff; padding: 8px 14px; flex-wrap: wrap; }
.top a { color: #deebff; }
.top select, .top input { background: #fff; }
.top .brand { font-size: 16px; margin-right: 8px; }
.top .me { margin-left: auto; }
.top form { margin: 0; }
.top #bell { color: #172b4d; }
.panel { position: absolute; right: 12px; top: 48px; width: 380px; max-height: 420px; overflow: auto; background: #fff; border: 1px solid #c1c7d0; box-shadow: 0 4px 12px rgba(0,0,0,.15); padding: 8px; z-index: 10; }
.panel .n { border-bottom: 1px solid #ebecf0; padding: 6px 0; }
.panel .n.unread { font-weight: 600; }
main { padding: 14px; position: relative; }
.row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin: 8px 0; }
.board { display: flex; gap: 10px; align-items: flex-start; overflow-x: auto; padding-bottom: 8px; }
.col { background: #ebecf0; border-radius: 4px; min-width: 220px; width: 220px; padding: 8px; min-height: 120px; }
.col.over { background: #dfe1e6; }
.col h3 { margin: 0 0 6px; font-size: 13px; text-transform: uppercase; color: #5e6c84; }
.cnt { background: #c1c7d0; border-radius: 10px; padding: 0 6px; font-size: 11px; }
.card { background: #fff; border-radius: 3px; padding: 6px 8px; margin-bottom: 6px; box-shadow: 0 1px 0 #c1c7d0; cursor: grab; }
.card .meta { color: #6b778c; font-size: 12px; margin-top: 4px; }
.card .title { margin-top: 2px; }
table { border-collapse: collapse; width: 100%; background: #fff; }
th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #ebecf0; vertical-align: top; }
.card-box { background: #fff; padding: 12px; border-radius: 4px; margin-bottom: 12px; box-shadow: 0 1px 1px rgba(0,0,0,.08); }
.grid { display: grid; grid-template-columns: 2fr 1fr; gap: 14px; }
.issue-row { display: flex; gap: 8px; align-items: center; padding: 4px 0; border-bottom: 1px solid #ebecf0; }
.issue-row .t { flex: 1; }
.auth { max-width: 360px; margin: 80px auto; background: #fff; padding: 22px; border-radius: 4px; box-shadow: 0 1px 3px rgba(0,0,0,.15); }
.comment { border-bottom: 1px solid #ebecf0; padding: 6px 0; }
.comment .who { font-size: 12px; color: #6b778c; }
.badge { display: inline-block; font-size: 11px; background: #dfe1e6; border-radius: 3px; padding: 0 5px; margin-left: 4px; }
svg.burndown { width: 100%; max-width: 680px; background: #fff; }
svg.burndown .actual { fill: none; stroke: #0052cc; stroke-width: 2; }
svg.burndown .ideal { fill: none; stroke: #97a0af; stroke-dasharray: 4 4; }
pre.raw { white-space: pre-wrap; background: #f4f5f7; padding: 6px; }

