      </section>`;
  }).join('');
  $('#main').innerHTML = `
    <div class="grid">
      <div>
        <h2>Backlog</h2>
        <div class="card-box">${backlogItems.map(row).join('') || '<p class="muted">Backlog is empty.</p>'}</div>
