            <div class="issue-row"><span class="t">${esc(l.type)} <a href="#/issue/${esc(l.target)}">${esc(l.target)}</a></span>
              <button class="link danger" data-unlink="${idx}">remove</button></div>`).join('') || '<p class="muted">No links.</p>'}
